"@

try {
    $gifBytes = [System.Convert]::FromBase64String($gifBase64)
    $ms = New-Object System.IO.MemoryStream(,$gifBytes)
    $image = [System.Drawing.Image]::FromStream($ms)
} catch {
    Write-Output "[-] Failed to decode the embedded GIF. Ensure the base64 string is valid."
    exit 1
}

$form = New-Object System.Windows.Forms.Form
$form.Text = "Processing - Please Wait..."
$form.Size = New-Object System.Drawing.Size(300,300)
$form.StartPosition = "CenterScreen"
$form.TopMost = $true

$pictureBox = New-Object System.Windows.Forms.PictureBox
$pictureBox.Dock = "Fill"
$pictureBox.SizeMode = "StretchImage"
$pictureBox.Image = $image
$form.Controls.Add($pictureBox)

$form.Show()

$dumpFolder = Join-Path -Path (Get-Location) -ChildPath "ProcessDumps"
if (-not (Test-Path $dumpFolder)) {
    New-Item -ItemType Directory -Path $dumpFolder | Out-Null
}
Write-Output "[*] Process dumps will be stored in: $dumpFolder"

Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public enum MINIDUMP_TYPE : int {
    MiniDumpNormal = 0x00000000,
    MiniDumpWithDataSegs = 0x00000001,
    MiniDumpWithFullMemory = 0x00000002,
    MiniDumpWithHandleData = 0x00000004,
    MiniDumpFilterMemory = 0x00000008,
    MiniDumpScanMemory = 0x00000010,
    MiniDumpWithUnloadedModules = 0x00000020,
    MiniDumpWithIndirectlyReferencedMemory = 0x00000040,
    MiniDumpFilterModulePaths = 0x00000080,
    MiniDumpWithProcessThreadData = 0x00000100,
    MiniDumpWithPrivateReadWriteMemory = 0x00000200,
    MiniDumpWithoutOptionalData = 0x00000400,
    MiniDumpWithFullMemoryInfo = 0x00000800,
    MiniDumpWithThreadInfo = 0x00001000,
    MiniDumpWithCodeSegs = 0x00002000,
    MiniDumpWithoutAuxiliaryState = 0x00004000,
    MiniDumpWithFullAuxiliaryState = 0x00008000,
    MiniDumpWithPrivateWriteCopyMemory = 0x00010000,
    MiniDumpIgnoreInaccessibleMemory = 0x00020000,
    MiniDumpWithTokenInformation = 0x00040000,
    MiniDumpWithModuleHeaders = 0x00080000,
    MiniDumpFilterTriage = 0x00100000,
    MiniDumpValidTypeFlags = 0x001fffff,
}
public class MiniDumper {
    [DllImport("Dbghelp.dll", SetLastError = true)]
    public static extern bool MiniDumpWriteDump(
        IntPtr hProcess,
        int ProcessId,
        IntPtr hFile,
        MINIDUMP_TYPE DumpType,
        IntPtr ExceptionParam,
        IntPtr UserStreamParam,
        IntPtr CallbackParam
    );
}
"@ -ReferencedAssemblies "System.dll"

$wmiprocs = Get-CimInstance -ClassName Win32_Process
$totalProcs = $wmiprocs.Count
$count = 0

foreach ($wmiProc in $wmiprocs) {
    $count++
    $procId = $wmiProc.ProcessId
    $procName = $wmiProc.Name

    [System.Windows.Forms.Application]::DoEvents()

    Write-Output ("[*] Processing process {0} of {1}: {2} (PID: {3})" -f $count, $totalProcs, $procName, $procId)

    try {
        $proc = Get-Process -Id $procId -ErrorAction Stop
    } catch {
        Write-Output "[-] Unable to access process information for PID $procId ($procName). Skipping..."
        continue
    }
    
    $safeName = $procName
    foreach ($char in [System.IO.Path]::GetInvalidFileNameChars()) {
        $safeName = $safeName -replace [regex]::Escape($char), "_"
    }
    
    $dumpFile = Join-Path -Path $dumpFolder -ChildPath ("{0}_{1}.dmp" -f $safeName, $procId)
    Write-Output "[*] Dumping process: $procName (PID: $procId) to $dumpFile"
    
    try {
        $fileStream = [System.IO.File]::Open($dumpFile, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
    } catch {
        Write-Output "[-] Failed to open file $dumpFile for writing. Skipping PID $procId."
        continue
    }
    
    $dumpType = [MINIDUMP_TYPE]::MiniDumpWithFullMemory
    try {
        $result = [MiniDumper]::MiniDumpWriteDump($proc.Handle, $procId, $fileStream.Handle, $dumpType, [IntPtr]::Zero, [IntPtr]::Zero, [IntPtr]::Zero)
        $fileStream.Close()
    } catch {
        Write-Output "[-] Exception occurred while dumping process $($procId): $($_)"
        $fileStream.Close()
        continue
    }
    
    if ($result) {
        Write-Output "[+] Successfully dumped process $procName (PID: $procId)."
    } else {
        $errorCode = [System.Runtime.InteropServices.Marshal]::GetLastWin32Error()
        Write-Output "[-] Failed to dump process $($procId). Error code: $errorCode"
    }
}

$form.Close()
Write-Output "[*] Memory dump process completed. Extracting file paths..."

$zipUrl = "https://download.ericzimmermanstools.com/net9/bstrings.zip"
$zipFile = ".\bstrings.zip"
$destinationPath = ".\"

Write-Output "Downloading bstrings.zip from $zipUrl ..."
Invoke-WebRequest -Uri $zipUrl -OutFile $zipFile

Write-Output "Unzipping $zipFile ..."
Expand-Archive -Path $zipFile -DestinationPath $destinationPath -Force

Write-Output "Running bstrings.exe -d ProcessDumps --lr win_path -o .\paths.txt ..."
& .\bstrings.exe -d ProcessDumps --lr win_path -o .\paths.txt

Write-Output "Done. The output has been saved to .\paths.txt"

<#
.SYNOPSIS
    Performs an advanced forensic scan of file signatures.
.DESCRIPTION
    This script reads file paths (Windows-style) from "paths.txt" in the current directory.
    For each path, it:
      - Checks if the file exists.
      - If not, marks it as "File not found."
      - If it exists, uses Get-AuthenticodeSignature to determine whether the file is signed.
      - It then categorizes the signature as:
          • "Valid" if the signature is valid,
          • "Not Signed" if the file isn’t signed,
          • "Invalid: <status>" if some other status is returned.
      - When a certificate is present, its subject and issuer are recorded.
    A progress bar is displayed during the scan, and the total elapsed time is shown at the end.
    Finally, results are exported to a CSV file named ScanResults.csv.
.NOTES
    Must be run as Administrator.
    Ensure a file named paths.txt (one full file path per line) exists in the same directory.
#>

Write-Host "@ -ForegroundColor Red"
Write-Host ""
Write-Host "  Made by UnMonsieur - " -ForegroundColor Blue -NoNewline
Write-Host -ForegroundColor Red "discord.gg/redlotus"
Write-Host ""

# Function to check if running as Admin.
function Test-Admin {
    $currentUser = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
    return $currentUser.IsInRole([Security.Principal.WindowsBuiltinRole]::Administrator)
}
if (!(Test-Admin)) {
    Write-Warning "Please Run This Script as Admin."
    Start-Sleep -Seconds 10
    exit
}

Start-Sleep -Seconds 3
Clear-Host

$host.privatedata.ProgressForegroundColor = "red"
$host.privatedata.ProgressBackgroundColor = "black"

$pathsFilePath = "paths.txt"
if (-Not (Test-Path -Path $pathsFilePath)) {
    Write-Warning "The file $pathsFilePath does not exist."
    Start-Sleep -Seconds 10
    exit
}

# Read file paths from paths.txt and filter out empty lines.
$paths = Get-Content $pathsFilePath | Where-Object { $_.Trim() -ne "" }
if ($paths.Count -eq 0) {
    Write-Warning "No valid file paths found in $pathsFilePath."
    exit
}

$stopwatch = [Diagnostics.Stopwatch]::StartNew()

$results = @()
$count = 0
$totalCount = $paths.Count
$progressID = 1

foreach ($path in $paths) {
    $progress = [int]($count / $totalCount * 100)
    Write-Progress -Activity "Scanning paths..." -Status "$progress% Complete:" -PercentComplete $progress -Id $progressID
    $count++

    $fileName = Split-Path $path -Leaf

    $fileDetails = New-Object PSObject
    $fileDetails | Add-Member -MemberType NoteProperty -Name "Name" -Value $fileName
    $fileDetails | Add-Member -MemberType NoteProperty -Name "Path" -Value $path

    if (-Not (Test-Path $path)) {
        $fileDetails | Add-Member -MemberType NoteProperty -Name "Exists" -Value $false
        $fileDetails | Add-Member -MemberType NoteProperty -Name "SignatureStatus" -Value "File not found"
        $fileDetails | Add-Member -MemberType NoteProperty -Name "CertificateSubject" -Value ""
        $fileDetails | Add-Member -MemberType NoteProperty -Name "CertificateIssuer" -Value ""
    }
    else {
        $fileDetails | Add-Member -MemberType NoteProperty -Name "Exists" -Value $true
        try {
            $sig = Get-AuthenticodeSignature $path -ErrorAction Stop
            # Determine signature validity.
            if ($sig.Status -eq "Valid") {
                $statusText = "Valid"
            }
            elseif ($sig.Status -eq "NotSigned") {
                $statusText = "Not Signed"
            }
            else {
                $statusText = "Invalid: $($sig.Status)"
            }
            $fileDetails | Add-Member -MemberType NoteProperty -Name "SignatureStatus" -Value $statusText
            if ($sig.SignerCertificate) {
                $fileDetails | Add-Member -MemberType NoteProperty -Name "CertificateSubject" -Value $sig.SignerCertificate.Subject
                $fileDetails | Add-Member -MemberType NoteProperty -Name "CertificateIssuer" -Value $sig.SignerCertificate.Issuer
            }
            else {
                $fileDetails | Add-Member -MemberType NoteProperty -Name "CertificateSubject" -Value ""
                $fileDetails | Add-Member -MemberType NoteProperty -Name "CertificateIssuer" -Value ""
            }
        }
        catch {
            $fileDetails | Add-Member -MemberType NoteProperty -Name "SignatureStatus" -Value ("Error: " + $_.Exception.Message)
            $fileDetails | Add-Member -MemberType NoteProperty -Name "CertificateSubject" -Value ""
            $fileDetails | Add-Member -MemberType NoteProperty -Name "CertificateIssuer" -Value ""
        }
    }
    $results += $fileDetails
}

$stopwatch.Stop()
$time = "{0:00}:{1:00}:{2:00}.{3:000}" -f $stopwatch.Elapsed.Hours, $stopwatch.Elapsed.Minutes, $stopwatch.Elapsed.Seconds, $stopwatch.Elapsed.Milliseconds

Write-Host ""
Write-Host "The scan took $time to run." -ForegroundColor Yellow

$csvPath = Join-Path -Path (Get-Location) -ChildPath "ScanResults.csv"
$results | Export-Csv -Path $csvPath -NoTypeInformation -Encoding UTF8
Write-Host "Scan results have been saved to '$csvPath'." -ForegroundColor Green


